function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
const COLOR_PRESETS=[['초록','#58cc02'],['파랑','#2878d7'],['남색','#5264c6'],['보라','#9163cc'],['주황','#ed8c24'],['회색','#535f59']];
function rgb(hex){return hex.slice(1).match(/../g).map(x=>parseInt(x,16))}
function mix(a,b,ratio){return '#'+rgb(a).map((v,i)=>Math.round(v*(1-ratio)+rgb(b)[i]*ratio).toString(16).padStart(2,'0')).join('')}
function luminance(color){return rgb(color).map(v=>{v/=255;return v<=.04045?v/12.92:((v+.055)/1.055)**2.4}).reduce((sum,v,i)=>sum+v*[.2126,.7152,.0722][i],0)}
function contrast(a,b){const x=luminance(a),y=luminance(b);return (Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
function readableAccent(color,backgrounds,dark){for(let i=0;i<=20;i++){const candidate=mix(color,dark?'#ffffff':'#000000',i/20);if(backgrounds.every(background=>contrast(candidate,background)>=4.5))return candidate}return dark?'#ffffff':'#000000'}
function applyTheme(){
  const root=document.documentElement,dark=db.theme==='system'?matchMedia('(prefers-color-scheme: dark)').matches:db.theme==='dark';root.dataset.theme=dark?'dark':'light';
  const primary=/^#[0-9a-f]{6}$/i.test(db.primaryColor||'')?db.primaryColor:'#58cc02';
  const foreground=contrast(primary,'#17211b')>=4.5?'#17211b':contrast(primary,'#ffffff')>=4.5?'#ffffff':'#000000';
  const secondary=mix(dark?'#1d2421':'#ffffff',primary,dark?.18:.1),highlight=mix(dark?'#1d2421':'#ffffff',primary,dark?.28:.17);
  const tokens={'--color-primary':primary,'--color-primary-text':foreground,'--color-secondary':secondary,'--color-highlight':highlight,'--color-primary-hover':mix(primary,foreground==='#ffffff'?'#000000':'#ffffff',.1),'--color-primary-shadow':mix(primary,'#000000',.2),'--color-accent-text':readableAccent(primary,[dark?'#171b19':'#ffffff',secondary,highlight],dark)};
  for(const [name,value]of Object.entries(tokens))root.style.setProperty(name,value);
}
function setPrimaryColor(value){if(!/^#[0-9a-f]{6}$/i.test(value))return false;db.primaryColor=value.toLowerCase();applyTheme();save();document.querySelectorAll('[data-color]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.color===db.primaryColor)));if($('#primary-color'))$('#primary-color').value=db.primaryColor;if($('#primary-hex')&&document.activeElement!==$('#primary-hex'))$('#primary-hex').value=db.primaryColor;if($('#color-error'))$('#color-error').textContent='';return true}

