function stats(h=profile().history){const correct=h.reduce((a,r)=>a+r.correct,0),total=h.reduce((a,r)=>a+r.total,0);const dates=[...new Set(h.map(r=>r.date))].sort().reverse();let streak=0,d=new Date();if(!dates.includes(today()))d.setDate(d.getDate()-1);while(dates.includes(dateKey(d))){streak++;d.setDate(d.getDate()-1)}return{count:h.length,score:h.reduce((a,r)=>a+r.score,0),correct,total,rate:total?Math.round(correct/total*100):0,streak}}
const achievementDefs=[['first','첫걸음','첫 번째 학습 완료',1,s=>s.count,'🌱'],['seven','꾸준한 시작','누적 7회 학습 완료',7,s=>s.count,'📗'],['thirty','학습의 습관','누적 30회 학습 완료',30,s=>s.count,'📚'],['hundred','열정적인 학습자','누적 100회 학습 완료',100,s=>s.count,'🏆'],['streak3','3일 연속 학습','3일 연속 학습 완료',3,s=>s.streak,'🔥'],['streak7','7일 연속 학습','7일 연속 학습 완료',7,s=>s.streak,'☀️'],['hard','고난도 도전','난이도 5 표현 학습 완료',1,()=>profile().history.some(r=>r.difficulty===5)?1:0,'💎'],['perfect','완벽한 하루','퀴즈의 모든 문제 정답',1,()=>profile().history.some(r=>r.correct===r.total)?1:0,'⭐']];
function achievementSnackbar(names){if(!names.length)return;let bar=$('#achievement-snackbar');if(!bar){bar=document.createElement('div');bar.id='achievement-snackbar';bar.setAttribute('role','status');bar.setAttribute('aria-live','polite');document.body.appendChild(bar)}clearTimeout(achievementSnackbar.timer);bar.innerHTML=`<span class="achievement-snackbar-icon">${icon('achievements')}</span><div><b>업적 달성</b><span>${names.map(esc).join(' · ')}</span></div><button aria-label="업적 알림 닫기">닫기</button>`;bar.querySelector('button').onclick=()=>bar.remove();achievementSnackbar.timer=setTimeout(()=>bar.remove(),6500)}
