function auth(){const signup=page==='signup';return `<section class="auth"><h1>${signup?'회원가입':'로그인'}</h1><p class="muted">전공 영어 학습</p><div class="card">${localMode()?'<p class="hint">계정과 학습 기록은 이 기기에 저장됩니다.</p>':''}<form id="auth-form"><label class="field">이메일 또는 아이디<input name="identity" autocomplete="username" required maxlength="100" placeholder="이메일 또는 아이디를 입력하세요"></label><label class="field">비밀번호<input name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required ${signup?'minlength="8"':''} placeholder="${signup?'영문과 숫자를 포함한 8자 이상':'비밀번호를 입력하세요'}"></label>${signup?'<label class="field">비밀번호 확인<input name="confirm" type="password" autocomplete="new-password" required placeholder="비밀번호를 한 번 더 입력하세요"></label>':''}<p id="form-error" class="error" role="alert">${!localMode()&&!isOnline()?'오프라인 상태에서는 로그인 및 회원가입을 할 수 없습니다.':''}</p><button class="primary" type="submit">${signup?'회원가입':'로그인'}</button></form>${localMode()&&!signup?'<div class="example-login"><b>예시 계정</b><p>demo@example.com<br>비밀번호: Demo1234!</p><button class="wide" id="example-login">예시 계정 로그인</button></div>':''}<button class="textbtn wide" data-nav="${signup?'login':'signup'}">${signup?'이미 계정이 있나요? 로그인':'처음 오셨나요? 회원가입'}</button></div><div class="divider">계정 없이 이용</div><button class="wide" id="guest">일일 학습 시작</button><p class="auth-footer">${localMode()?'로컬 계정과 랭킹은 이 기기에 저장됩니다.<br>다른 기기와의 공유는 백업 내보내기·불러오기를 이용하세요.':'인증·랭킹·동기화는 서버 연결이 필요합니다.<br>일일 학습은 기기에 저장됩니다.'}</p></section>`}
