function daily(){const p=profile(),s=stats(),majorStats=stats(p.history.filter(r=>r.major===p.major)),draw=currentDraw(),w=findWord(draw?.id),total=expressions.filter(e=>e.major===p.major).length,done=p.completed[p.major].length,remaining=total-done;return `<div class="page-head"><div><h1>매일 표현</h1><p class="muted">${new Intl.DateTimeFormat('ko-KR',{dateStyle:'long'}).format(new Date())}</p></div><span class="tag">${MAJORS[p.major]}</span></div><div class="grid"><section class="card hero"><div class="expression-sheet"><div class="expression-sheet-heading"><h2>${draw?.done?'학습 완료':w?(draw.key.split(':')[0]!==today()?'미완료 학습':'오늘의 표현'):'표현 뽑기'}</h2><span class="expression-count" aria-label="전공 표현 ${total}개 중 ${done}개 완료">${done} / ${total}</span></div>${draw&&!draw.done&&draw.key.split(':')[0]!==today()?`<p class="muted">${draw.key.split(':')[0]}에 뽑은 표현입니다. 이어서 학습하세요.</p>`:''}<div class="slot" id="slot"><div>${w?`<strong>${esc(w.english)}</strong><small class="draw-probability">${probabilityText(draw.probability)}</small><p>${esc(w.meaning)}</p><span class="tag">난이도 ${w.difficulty} / 5</span>`:'<strong>오늘의 표현을<br>뽑아보세요</strong>'}</div></div></div>${draw?.done?`<div class="hint success">학습 완료 · ${draw.score}점</div>`:''}${w&&!draw.done?'<button class="primary wide" id="start">학습 시작</button>':`<button class="primary wide" id="draw" ${remaining<=0?'disabled':''}>${remaining<=0?'남은 표현이 없습니다':draw?.done?'다음 표현 뽑기':'표현 뽑기'}</button>`}${w?`<div class="similar"><div class="row"><h3>관련 표현</h3><button id="speak" data-text="${esc(w.english)}">발음 듣기</button></div>${w.similar?.length?w.similar.map(x=>`<p><b>${esc(x.english)}</b><br><small>${esc(x.meaning)}</small></p>`).join(''):'<p class="muted">등록된 관련 표현이 없습니다.</p>'}</div>`:''}<button class="wide draw-test-button" id="test-draw">추첨 테스트</button><p class="draw-note muted">4가지 유형 중 무작위 2가지로 학습합니다.<br>표현 6개마다 최근 표현 짝 맞추기가 추가됩니다.</p></section><aside class="stack"><button class="countdown-link" id="open-falling" aria-label="단어 카운트다운 게임하기"><span class="countdown-icon">${icon('records')}</span><span><b>단어 카운트다운</b><small>전공 표현으로 시간 기록에 도전</small></span><span class="countdown-arrow" aria-hidden="true">›</span></button><section class="card learning-totals" aria-label="누적 학습 기록"><div class="summary-row"><span>지금까지 푼 문제</span><b>${s.total.toLocaleString()}문제</b></div><div class="summary-row"><span>누적 점수</span><b>${s.score.toLocaleString()}점</b></div></section></aside></div><section class="daily-study-summary" aria-label="선택 전공 학습 통계"><h2>${esc(MAJORS[p.major])} 학습 통계</h2><div class="stats">${[['총 학습 횟수',majorStats.count+'회'],['총 획득 점수',majorStats.score+'점'],['정답률',majorStats.rate+'%'],['연속 학습 일수',majorStats.streak+'일']].map(([a,b])=>`<div class="card"><small>${a}</small><div class="stat">${b}</div></div>`).join('')}</div></section>`}

function shuffled(a){const result=[...a];for(let i=result.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[result[i],result[j]]=[result[j],result[i]]}return result}
function makeWordBank(w){const correct=w.english.trim().split(/\s+/),excluded=new Set(correct.map(t=>t.toLowerCase()));const candidates=[...new Set([...expressions.filter(e=>e.major===w.major&&e.id!==w.id).flatMap(e=>e.english.split(/\s+/)), 'signal','current','voltage','network','power','data'].filter(t=>t&&!excluded.has(t.toLowerCase())).map(t=>t.toLowerCase()))];const extras=shuffled(candidates).slice(0,3);return shuffled([...correct,...extras].map((text,id)=>({text,id})))}
const QUIZ_NAMES={choice:'뜻 선택',order:'단어 배열',speaking:'말하기',match:'짝 맞추기',scenario:'전공 상황'};
function recentPairs(word){const recent=[...(profile().history||[])].reverse().filter(r=>r.major===word.major);const seen=new Set(),meanings=new Set(),pairs=[];for(const w of [word,...recent.map(r=>({id:r.expressionId,english:r.english,meaning:r.meaning}))]){if(!w.id||!w.english||!w.meaning||seen.has(w.id)||meanings.has(w.meaning))continue;seen.add(w.id);meanings.add(w.meaning);pairs.push({id:w.id,english:w.english,meaning:w.meaning});if(pairs.length===4)break}return pairs}
function scenarioOptions(word){const anchors=word.major==='ee'?['ee-0','ee-10','ee-20','ee-36','ee-5']:['com-16','com-24','com-35','com-53','com-27'];const related=new Set((word.similar||[]).map(x=>x.english.toLowerCase()));const wrong=shuffled(expressions.filter(e=>anchors.includes(e.id)&&e.id!==word.id&&!related.has(e.english.toLowerCase()))).slice(0,3);return shuffled([{id:word.id,english:word.english},...wrong.map(e=>({id:e.id,english:e.english}))])}
function quizReady(q){const type=q.types[q.index];return type==='order'?q.chosen.length===q.word.english.trim().split(/\s+/).length:type==='choice'?q.choice!==null:type==='speaking'?q.repeats>=requiredRepeats:type==='match'?q.pairs.length>0&&q.pairs.every(p=>q.matches[p.id]):type==='scenario'?q.scenarioChoice!==null:false}
function connectPair(id){const q=quiz;if(!q||q.checked||!q.matchLeft)return;for(const key of Object.keys(q.matches))if(q.matches[key]===id)delete q.matches[key];q.matches[q.matchLeft]=id;q.matchLeft=null;render()}
function needsMatchingReview(word,review=false,onlyType=null){if(review||onlyType||!(word.quizTypes||[]).includes('match'))return false;const p=profile(),completed=p.completed?.[word.major]||[...new Set((p.history||[]).filter(r=>r.major===word.major).map(r=>r.expressionId))];return !completed.includes(word.id)&&(completed.length+1)%6===0}
function quizDraftKey(w,review){return (review?'review:':'learn:')+w.major+':'+w.id}
function saveQuizProgress(){if(quiz&&!isOnline())quiz.rankEligible=false;if(page!=='quiz'||!quiz||quiz.saved||quiz.returnReview||quiz.singleRetry)return;const p=profile();p.quizDrafts=p.quizDrafts||{};p.quizDrafts[quizDraftKey(quiz.word,quiz.review)]=JSON.parse(JSON.stringify(quiz));save()}
function restoreQuizProgress(w,review){const p=profile(),draft=p.quizDrafts?.[quizDraftKey(w,review)];if(!draft||draft.saved||draft.returnReview||draft.word?.id!==w.id||!Array.isArray(draft.types)||!draft.types.length||!Number.isInteger(draft.index)||draft.index<0||draft.index>=draft.types.length)return false;if(!review&&(p.completed[w.major]||[]).includes(w.id))return false;quiz=JSON.parse(JSON.stringify(draft));page='quiz';render();return true}
function startQuiz(w,review=false,onlyType=null){if(!w)return;if(!onlyType&&restoreQuizProgress(w,review))return;const available=[...new Set((onlyType?[onlyType]:(w.quizTypes||['choice','order','speaking'])).filter(t=>Object.hasOwn(QUIZ_NAMES,t)&&(t!=='scenario'||w.scenario?.prompt)))];const types=onlyType?available:shuffled(available.filter(t=>t!=='match')).slice(0,2);const bonusMatch=needsMatchingReview(w,review,onlyType);if(bonusMatch)types.push('match');if(!types.length){toast('등록된 퀴즈가 없습니다.');return}const pairs=types.includes('match')?shuffled(recentPairs(w)):[];quiz={rankEligible:isOnline(),returnPage:['wrong-review','study-log','records','history','daily'].includes(page)?page:'daily',singleRetry:!!onlyType,word:w,types,bonusMatch,index:0,answers:[],tokens:makeWordBank(w),chosen:[],choice:null,repeats:0,checked:false,review,drawKey:currentDraw()?.key||drawKey(),major:w.major,pairs,matchChoices:shuffled(pairs),matches:{},matchLeft:null,scenarioOptions:types.includes('scenario')?scenarioOptions(w):[],scenarioChoice:null};page='quiz';render()}

function retrySavedQuestion(){const r=profile().history.find(r=>r.id===historyReview?.recordId),answer=r?.answers[historyReview.index];if(!r||!answer)return;const destination={...historyReview};const w={id:r.expressionId,english:r.english,meaning:r.meaning,major:r.major,difficulty:r.difficulty||1,scenario:answer.type==='scenario'?{prompt:answer.prompt||findWord(r.expressionId)?.scenario?.prompt}:undefined};startQuiz(w,true,answer.type);if(answer.type==='match'&&answer.pairs){quiz.pairs=answer.pairs.map(p=>({id:p.id,english:p.english,meaning:p.meaning}));quiz.matchChoices=shuffled(quiz.pairs)}if(answer.type==='scenario'&&answer.options){quiz.scenarioOptions=answer.options.map((english,i)=>({id:i===answer.correctIndex?w.id:'saved-'+i,english}))}quiz.returnReview=destination;render();window.scrollTo(0,0)}
function returnToSavedReview(){const destination=quiz?.returnReview;if(!destination)return;historyReview=destination;quiz=null;page='answer-review';render();window.scrollTo(0,0)}

function quizView(){
 const q=quiz,w=q.word,type=q.types[q.index],a=q.answers[q.index];
 const titles={order:'필요한 단어를 골라 올바른 순서로 배열하세요',choice:'영어 표현에 맞는 뜻을 고르세요',speaking:`표현을 소리 내어 ${requiredRepeats}번 말해보세요`,match:'영어 표현과 뜻의 짝을 맞추세요',scenario:'상황에 맞는 영어 표현을 고르세요'};
 let body='';
 if(type==='order')body=`<div class="answerbox" aria-label="선택한 단어">${q.chosen.map(id=>`<button data-remove="${id}" ${q.checked?'disabled':''}>${esc(q.tokens.find(t=>t.id===id).text)} ×</button>`).join(' ')||'<span class="muted">아래 단어를 차례대로 선택하세요</span>'}</div><p class="muted word-count">필요한 단어 ${w.english.trim().split(/\s+/).length}개 (${q.chosen.length}/${w.english.trim().split(/\s+/).length})</p><div class="wordbank">${q.tokens.map(t=>`<button data-token="${t.id}" ${q.chosen.includes(t.id)||q.checked||q.chosen.length>=w.english.trim().split(/\s+/).length?'disabled':''}>${esc(t.text)}</button>`).join('')}</div>`;
 if(type==='choice'){q.options=q.options||shuffled([w.meaning,...shuffled(expressions.filter(e=>e.major===w.major&&e.id!==w.id&&e.meaning!==w.meaning)).slice(0,3).map(e=>e.meaning)]);body=`<div class="choices">${q.options.map((x,i)=>`<button class="choice ${q.choice===i?'selected':''}" data-choice="${i}" ${q.checked?'disabled':''}>${i+1}. ${esc(x)}</button>`).join('')}</div>`}
 if(type==='speaking')body=`<div class="center"><button id="speak" data-text="${esc(w.english)}">발음 듣기</button><p class="stat">${q.repeats} / ${requiredRepeats}</p><button id="repeat" class="secondary" ${q.repeats>=requiredRepeats||q.checked?'disabled':''}>소리 내어 말했어요 ✓</button><p class="muted">소리 내어 읽은 뒤 완료를 눌러주세요. 자동 발음 채점은 하지 않습니다.</p></div>`;
 if(type==='match')body=`<p class="muted match-guide">영어를 선택한 뒤 오른쪽 뜻을 선택하세요. 연결한 영어를 다시 눌러 바꿀 수 있습니다.${q.bonusMatch?' 표현 6개 단위로 진행하는 추가 복습입니다.':q.pairs.length===1?' 저장된 표현 한 쌍을 복습합니다.':''}</p><div class="matching-headings"><b>영어 표현</b><b>한국어 뜻</b></div><div class="matching-board"><div>${q.pairs.map((p,i)=>`<button class="match-tile ${q.matchLeft===p.id?'selected':''} ${q.matches[p.id]?'connected':''}" data-match-left="${esc(p.id)}" aria-pressed="${q.matchLeft===p.id}" ${q.checked?'disabled':''}><span class="match-label"><b class="match-number">${i+1}</b><span>${esc(p.english)}</span></span><small>${q.matchLeft===p.id?'선택 중 · 뜻을 누르세요':q.matches[p.id]?'연결: '+esc(q.matchChoices.find(x=>x.id===q.matches[p.id])?.meaning):'미연결'}</small></button>`).join('')}</div><div>${q.matchChoices.map(p=>{const left=q.pairs.find(x=>q.matches[x.id]===p.id);return `<button class="match-tile ${left?'connected':''}" data-match-right="${esc(p.id)}" ${q.checked?'disabled':''}><span class="match-label">${left?`<b class="match-number">${q.pairs.indexOf(left)+1}</b>`:'<b class="match-number unlinked">–</b>'}<span>${esc(p.meaning)}</span></span><small>${left?(q.pairs.indexOf(left)+1)+'번에 연결':'선택 가능'}</small></button>`}).join('')}</div></div><p class="word-count muted">${Object.keys(q.matches).length} / ${q.pairs.length}쌍 연결</p>`;
 if(type==='scenario')body=`<div class="choices">${q.scenarioOptions.map((option,i)=>`<button class="choice ${q.scenarioChoice===i?'selected':''}" data-scenario-choice="${i}" ${q.checked?'disabled':''}>${i+1}. ${esc(option.english)}</button>`).join('')}</div>`;
 const prompt=type==='order'?w.meaning:type==='scenario'?w.scenario.prompt:type==='match'?'최근 배운 표현 복습':w.english;
 return `<section class="quiz"><div class="row"><button id="exit-quiz">← 나가기</button><b>${q.index+1} / ${q.types.length} 문제 ${q.returnReview?'· 다시 풀기':q.review?'· 복습':''}</b></div><div class="progress"><span style="width:${(q.index+(q.checked?1:0))/q.types.length*100}%"></span></div><ol class="quiz-stages" aria-label="학습 단계">${q.types.map((t,i)=>`<li class="${i===q.index?'current':i<q.index?'finished':''}" ${i===q.index?'aria-current="step"':''}><span>${i+1}</span>${QUIZ_NAMES[t]}</li>`).join('')}</ol><div class="quiz-expression ${type==='scenario'?'scenario-prompt':''}"><span class="eyebrow">${MAJORS[w.major]} · <strong class="quiz-type-name">${QUIZ_NAMES[type]}</strong></span><h2>${esc(prompt)}</h2>${type==='speaking'?`<p>${esc(w.meaning)}</p>`:''}</div><h3>${titles[type]}</h3>${body}${q.checked?`<div class="feedback ${a.correct?'':'wrong'}" role="status"><b>${a.correct?'✓ 정답입니다!':'✕ 오답입니다.'}</b><p>내 답: ${esc(a.given)}</p><p>정답: ${esc(a.answer)}</p>${type==='match'?'<small>모든 쌍을 맞히면 한 문제 정답으로 처리합니다.</small>':''}</div><button class="primary wide" id="next" style="margin-top:24px">${q.index===q.types.length-1?'학습 완료':q.types[q.index+1]==='match'&&q.bonusMatch?'최근 표현 복습 →':'다음 문제 →'}</button>`:`<button class="primary wide" id="submit" style="margin-top:24px" ${quizReady(q)?'':'disabled'}>정답 확인</button>`}</section>`;
}
function gradeAnswer(q){const type=q.types[q.index],w=q.word;
 if(type==='match'){const pairs=q.pairs.map(p=>({id:p.id,english:p.english,meaning:p.meaning,selectedId:q.matches[p.id],selectedMeaning:q.matchChoices.find(x=>x.id===q.matches[p.id])?.meaning||'',correct:q.matches[p.id]===p.id}));return {type,correct:pairs.every(p=>p.correct),given:pairs.map(p=>p.english+' → '+p.selectedMeaning).join(' / '),answer:pairs.map(p=>p.english+' → '+p.meaning).join(' / '),pairs}}
 if(type==='scenario'){const option=q.scenarioOptions[q.scenarioChoice];return {type,correct:option.id===w.id,given:option.english,answer:w.english,prompt:w.scenario.prompt,options:q.scenarioOptions.map(x=>x.english),selectedIndex:q.scenarioChoice,correctIndex:q.scenarioOptions.findIndex(x=>x.id===w.id)}}
 const given=type==='order'?q.chosen.map(id=>q.tokens.find(t=>t.id===id).text).join(' '):type==='choice'?q.options[q.choice]:`${q.repeats}회 반복`;
 return {type,given,correct:type==='order'?given===w.english:type==='choice'?given===w.meaning:q.repeats>=requiredRepeats,answer:type==='choice'?w.meaning:w.english,options:type==='choice'?[...q.options]:undefined,selectedIndex:type==='choice'?q.choice:undefined,wordBank:type==='order'?q.tokens.map(t=>t.text):undefined,selectedWords:type==='order'?q.chosen.map(id=>q.tokens.find(t=>t.id===id).text):undefined,repetitions:type==='speaking'?q.repeats:undefined,requiredRepetitions:type==='speaking'?requiredRepeats:undefined};
}
// One short, non-interactive burst; independent of app rerenders and offline assets.
function celebrateCorrect(){
 document.querySelector('.confetti-burst')?.remove();
 const layer=document.createElement('div');layer.className='confetti-burst';layer.setAttribute('aria-hidden','true');
 const colors=['#58cc02','#ffc800','#1cb0f6','#ce82ff','#ff9600'];
 for(let i=0;i<48;i++){const piece=document.createElement('i'),left=i%2===0,distance=window.innerWidth*(.38+Math.random()*.18);piece.style.setProperty('--confetti-origin',left?'0%':'100%');piece.style.setProperty('--confetti-x',(left?distance:-distance)+'px');piece.style.setProperty('--confetti-y',(-220-Math.random()*180)+'px');piece.style.setProperty('--confetti-spin',((Math.random()-.5)*1080)+'deg');piece.style.setProperty('--confetti-color',colors[i%colors.length]);piece.style.setProperty('--confetti-delay',Math.random()*90+'ms');layer.appendChild(piece)}
 document.body.appendChild(layer);setTimeout(()=>layer.remove(),2300);
}
function submitAnswer(){const q=quiz;if(!q||q.checked||!quizReady(q))return;const answer=gradeAnswer(q);q.answers[q.index]=answer;q.checked=true;if(q.returnReview){returnToSavedReview();toast(answer.correct?'다시 풀기: 정답입니다.':'다시 풀기: 오답입니다. 정답을 확인하세요.');if(answer.correct)celebrateCorrect();return}render();if(answer.correct)celebrateCorrect()}

function finish(){if(quiz.saved)return;quiz.saved=true;const drafts=profile().quizDrafts;if(drafts){delete drafts[quizDraftKey(quiz.word,quiz.review)];save()}const correct=quiz.answers.filter(a=>a.correct).length;quiz.result={correct,total:quiz.types.length,score:quiz.review?0:correct*pointsPerCorrect};if(!quiz.review){const p=profile(),w=quiz.word;const result={rankEligible:quiz.rankEligible===true&&isOnline(),id:uid(),date:today(),scheduledDate:quiz.drawKey.split(':')[0],expressionId:w.id,english:w.english,meaning:w.meaning,major:w.major,difficulty:w.difficulty,correct,total:quiz.types.length,wrong:quiz.types.length-correct,score:correct*pointsPerCorrect,status:today()===quiz.drawKey.split(':')[0]?'done':'late',answers:quiz.answers};p.history.push(result);if(!p.completed[w.major].includes(w.id))p.completed[w.major].push(w.id);p.draws[quiz.drawKey]={...p.draws[quiz.drawKey],id:w.id,done:true,score:result.score};markPending(p);const awarded=checkAchievements();updateAchievementState();save();if(awarded.length)setTimeout(()=>achievementSnackbar(awarded),200);sync()}const destination=quiz.review?(quiz.returnPage||'daily'):'daily';quiz=null;page=destination;render();window.scrollTo(0,0);toast('학습을 완료했습니다.')}
function resultView(){return `<section class="auth center"><h1>${quiz.review?'복습 완료':'학습 완료'}</h1><p class="muted">${esc(quiz.word.english)} · ${esc(quiz.word.meaning)}</p><div class="card"><div class="result-ring" role="img" aria-label="정답률 ${Math.round(quiz.result.correct/quiz.result.total*100)}퍼센트" style="--result-progress:${quiz.result.correct/quiz.result.total*360}deg"><span>${Math.round(quiz.result.correct/quiz.result.total*100)}<small>%</small></span></div><div class="result-number">+${quiz.result.score}<small>점</small></div><p>정답 ${quiz.result.correct}개 · 오답 ${quiz.result.total-quiz.result.correct}개</p><p class="muted">${quiz.review?'복습은 기존 기록과 점수를 변경하지 않습니다.':'학습 결과가 이 기기에 저장되었습니다.'}</p></div>${quiz.returnReview?'<button class="primary wide" id="return-saved-review" style="margin-top:24px">문제 확인으로 돌아가기</button>':'<button class="primary wide" data-nav="daily" style="margin-top:24px">매일 표현으로 돌아가기 →</button>'}</section>`}
function locked(text){return `<section class="card locked"><h1>로그인이 필요합니다</h1><p class="muted">${text}</p><button class="primary" data-nav="login">로그인 화면으로</button></section>`}
function typeGradient(types){const total=types.reduce((s,t)=>s+t.count,0);if(!total)return 'var(--color-surface)';let at=0;return 'conic-gradient('+types.map((t,i)=>{const start=at;at+=t.count/total*100;return ['var(--color-primary)','var(--color-info)','var(--color-reward)','#9a75c9','#09a594'][i]+' '+start+'% '+at+'%'}).join(',')+')'}
let analysisScope='history';
const reportMetrics={history:'rate',records:'rate'};
const reportDates={history:null,records:null};
function reportData(history,major,asOf){const rows=history.filter(r=>r.date<=asOf),s=stats(rows),catalog=expressions.filter(w=>!major||w.major===major),learned=new Set(rows.map(r=>r.expressionId));const types=['order','choice','speaking','match','scenario'].map(type=>({type,count:rows.reduce((sum,r)=>sum+(r.answers||[]).filter(a=>a.type===type).length,0)}));const dates=[...new Set([...rows.map(r=>r.date),asOf])].sort().slice(-6);return {rows,s,learned:learned.size,levels:[1,2,3,4,5].map(level=>({level,total:catalog.filter(w=>w.difficulty===level).length,done:catalog.filter(w=>w.difficulty===level&&learned.has(w.id)).length})),types,trend:dates.map(date=>{const h=history.filter(r=>r.date<=date),statsAt=stats(h);return {date,learned:new Set(h.map(r=>r.expressionId)).size,rate:statsAt.rate,score:statsAt.score}})}}
function trendChart(points,key,label,unit){const width=320,height=104,pad=14,max=key==='rate'?100:Math.max(1,...points.map(p=>p[key])),coords=points.map((p,i)=>({x:points.length===1?width/2:pad+i*(width-2*pad)/(points.length-1),y:height-14-p[key]/max*(height-28),p}));return `<svg class="trend-chart readable-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="${label} 추이"><title>${points.map(p=>p.date+' '+p[key]+unit).join(', ')}</title>${[14,52,90].map(y=>`<path d="M14 ${y}H306" class="trend-baseline"/>`).join('')}<polyline points="${coords.map(c=>c.x+','+c.y).join(' ')}" fill="none" stroke="currentColor" stroke-width="2.5" stroke-linejoin="round"/>${coords.map((c,i)=>`<circle cx="${c.x}" cy="${c.y}" r="${i===coords.length-1?4:3}" fill="currentColor"/>`).join('')}</svg>`}
function analyticsView(history,major,scope){
 const firstStudyDate=history.length?history.map(r=>r.date).sort()[0]:today(),chosenDate=reportDates[scope],validDate=typeof chosenDate==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(chosenDate)&&chosenDate>=firstStudyDate&&chosenDate<=today(),options=[...new Set([...history.map(r=>r.date),today(),...(validDate?[chosenDate]:[])])].sort(),asOf=validDate?chosenDate:today(),at=options.indexOf(asOf),data=reportData(history,major,asOf),total=data.types.reduce((n,t)=>n+t.count,0),metrics=[['learned','학습한 표현','개'],['rate','정답률','%'],['score','누적 점수','점']],key=reportMetrics[scope]||'rate',active=metrics.find(m=>m[0]===key)||metrics[1],datePoints=data.trend.length<=3?data.trend:[data.trend[0],data.trend[Math.floor((data.trend.length-1)/2)],data.trend.at(-1)];
 return `<section class="learning-report readable-report" aria-label="${major?MAJORS[major]:'모든 전공'} 학습 분석"><div class="report-title"><h2>학습 분석</h2><span class="tag">${major?MAJORS[major]:'모든 전공'}</span></div><div class="report-date"><div class="report-asof"><label class="report-date-picker"><span class="sr-only">분석 날짜 선택</span><input type="date" data-analysis-date="${scope}" value="${esc(asOf)}" min="${esc(firstStudyDate)}" max="${today()}" aria-label="분석 날짜 선택"></label><small>이 날짜까지의 누적 기록</small></div><div><button data-report-scope="${scope}" data-report-date="${options[at-1]||''}" ${at===0?'disabled':''} aria-label="이전 학습일 분석">‹</button><button data-report-scope="${scope}" data-report-date="${today()}" ${asOf===today()?'disabled':''}>최근</button><button data-report-scope="${scope}" data-report-date="${options[at+1]||''}" ${at===options.length-1?'disabled':''} aria-label="다음 학습일 분석">›</button></div></div><div class="report-summary">${metrics.map(([k,label,unit])=>`<div><span>${label}</span><strong>${(data[k]??data.s[k]).toLocaleString()}<small>${unit}</small></strong></div>`).join('')}</div><div class="report-overview"><section><h3>난이도별 학습 현황</h3><p class="report-caption">완료한 표현 / 전체 표현</p><div class="level-list">${data.levels.map(l=>`<div class="level-row"><span>난이도 ${l.level}</span><div class="level-meter" role="progressbar" aria-label="난이도 ${l.level} 학습한 표현" aria-valuenow="${l.done}" aria-valuemin="0" aria-valuemax="${l.total||1}"><span style="width:${l.total?l.done/l.total*100:0}%"></span></div><b>${l.done}<small> / ${l.total}</small></b></div>`).join('')}</div></section><section><h3>학습 유형 분포</h3><p class="report-caption">완료한 문제 수 기준</p><div class="type-overview"><div class="type-donut" role="img" aria-label="${data.types.map(t=>QUIZ_NAMES[t.type]+' '+t.count+'문제').join(', ')}" style="background:${typeGradient(data.types)}"><span>${total}<small>문제</small></span></div><ul>${data.types.map((t,i)=>`<li><i class="type-dot type-${i}" aria-hidden="true"></i><span>${QUIZ_NAMES[t.type]}</span><b>${t.count}<small>문제</small></b></li>`).join('')}</ul></div></section></div><section class="report-trend-panel"><div class="report-trend-header"><h3>학습 추이</h3><small>최근 ${data.trend.length}개 기록일</small></div><div class="report-metric-tabs" role="group" aria-label="추이 지표">${metrics.map(([k,label])=>`<button data-report-metric="${k}" data-metric-scope="${scope}" aria-pressed="${k===key}">${label}</button>`).join('')}</div>${history.length?trendChart(data.trend,key,active[1],active[2]):'<p class="report-empty muted">학습을 완료하면 변화가 표시됩니다.</p>'}<div class="report-chart-dates">${datePoints.map(p=>`<span>${esc(p.date.slice(5).replace('-','.'))}</span>`).join('')}</div><details class="report-data-table"><summary>날짜별 수치 보기</summary><div><table><caption class="sr-only">학습 기록일별 누적 수치</caption><thead><tr><th scope="col">날짜</th><th scope="col">표현</th><th scope="col">정답률</th><th scope="col">점수</th></tr></thead><tbody>${data.trend.map(p=>`<tr><th scope="row">${esc(p.date)}</th><td>${p.learned}개</td><td>${p.rate}%</td><td>${p.score}점</td></tr>`).join('')}</tbody></table></div></details></section></section>`
}

function analysisLink(scope){return `<button class="wide analysis-link" data-open-analysis="${scope}"><span>학습 분석 보기</span><span aria-hidden="true">›</span></button>`}
function analysisPageView(){if(!db.session)return locked('학습 분석은 로그인 후 이용할 수 있습니다.');const p=profile(),major=analysisScope==='history'?p.major:null,h=major?p.history.filter(r=>r.major===major):p.history;return `<section class="analysis-page"><div class="page-head"><div><button id="close-analysis">← 뒤로 가기</button><h1>학습 분석</h1><p class="muted">${major?MAJORS[major]+' 전공':'모든 전공'}</p></div></div>${analyticsView(h,major,analysisScope)}</section>`}
let historyTab='major';
function historyView(){const tabs=`<div class="history-scope-tabs" role="group" aria-label="학습 기록 전공 범위"><button data-history-tab="all" aria-pressed="${historyTab==='all'}">전체 전공</button><button data-history-tab="major" aria-pressed="${historyTab==='major'}">선택 중인 전공${profile().major?' · '+esc(MAJORS[profile().major]):''}</button></div>`;return tabs+(historyTab==='all'?recordsView():historySelectedView())}
function historySelectedView(){if(!db.session)return locked('비로그인 사용자는 일일 학습만 이용할 수 있습니다. 학습 통계와 오답 복습은 로그인 후 이용할 수 있어요.');const p=profile(),h=p.history.filter(r=>r.major===p.major),s=stats(h),studyStart=h.length?h.map(r=>r.scheduledDate||r.date).sort()[0]:today(),y=month.getFullYear(),m=month.getMonth(),first=new Date(y,m,1).getDay(),days=new Date(y,m+1,0).getDate();let cells=Array(first).fill('<span></span>');for(let d=1;d<=days;d++){const k=dateKey(new Date(y,m,d)),rows=h.filter(r=>r.scheduledDate===k);const status=k>today()||k<studyStart?'':rows.length?(rows.some(r=>r.status==='done')?'done':'late'):'missed';cells.push(`<button class="day ${status} ${selectedDay===k?'chosen':''}" data-day="${k}" aria-label="${k} ${status==='done'?'완료':status==='late'?'늦게 완료':status==='missed'?'미완료':'학습 전'}">${d}</button>`)}return `<div class="page-head"><div><h1>학습 기록</h1><p class="muted">${MAJORS[p.major]} 전공</p></div></div><div class="history-calendar"><section class="card"><div class="row"><button id="prev-month" aria-label="이전 달">‹</button><h2>${y}년 ${m+1}월</h2><button id="next-month" aria-label="다음 달">›</button></div><div class="calendar">${'일월화수목금토'.split('').map(x=>`<span>${x}</span>`).join('')}${cells.join('')}</div><div class="legend"><span>🟢 완료</span><span>🟡 늦게 완료</span><span>🔴 미완료</span><span>⚪ 학습 전·미래</span></div></section></div><div class="history-links">${analysisLink('history')}<button class="wide analysis-link" data-nav="wrong-review"><span>오답 복습</span><span aria-hidden="true">›</span></button><button class="wide analysis-link" data-nav="study-log"><span>전체 학습 내역</span><span aria-hidden="true">›</span></button></div>`}
function sortedRecords(rows,scope){const mode=profile().listSort?.[scope]||'newest',item=r=>r.latest||r,wrong=r=>r.rows?r.rows.reduce((n,x)=>n+(Number(x.wrong)||0),0):(Number(r.wrong)||0);return rows.map((r,i)=>({r,i})).sort((a,b)=>{const x=item(a.r),y=item(b.r),recent=String(y.date||'').localeCompare(String(x.date||''));return (mode==='oldest'?-recent:mode==='wrong'?wrong(b.r)-wrong(a.r)||recent:mode==='name'?String(x.english||'').localeCompare(String(y.english||''),'en')||recent:recent)||(mode==='oldest'?a.i-b.i:b.i-a.i)}).map(x=>x.r)}
function recordSortControl(scope,count){const selected=profile().listSort?.[scope]||'newest';return `<div class="record-sort-bar"><small>${count}개 기록</small><label><span>정렬</span><select data-record-sort="${scope}" aria-label="기록 정렬">${[['newest','최신순'],['oldest','오래된순'],['wrong','오답 많은순'],['name','영어 표현순']].map(([value,label])=>`<option value="${value}" ${selected===value?'selected':''}>${label}</option>`).join('')}</select></label></div>`}
function historyDetailView(){if(!db.session)return locked('학습 기록은 로그인 후 확인할 수 있습니다.');const p=profile(),h=sortedRecords(p.history.filter(r=>r.major===p.major),page),wrong=page==='wrong-review';return `<header class="detail-page-heading"><button class="detail-back" data-nav="history" aria-label="학습 기록으로 돌아가기">←</button><div><h1>${wrong?'오답 복습':'전체 학습 내역'}</h1><p class="muted">${MAJORS[p.major]} 전공</p></div></header>${recordSortControl(page,wrong?h.filter(r=>r.wrong).length:h.length)}${wrong?`<section class="card wrong-review">${h.some(r=>r.wrong)?h.filter(r=>r.wrong).map(r=>`<article class="wrong-review-item"><div class="wrong-review-title"><b>${esc(r.english)}</b><span>${esc(r.meaning)}</span><small>${esc(r.date)}</small></div>${(r.answers||[]).filter(a=>!a.correct).map(a=>`<div class="wrong-answer-pair"><strong class="wrong-question-type">${esc(QUIZ_NAMES[a.type]||'문제')}</strong><div><span>내 답</span><p>${esc(a.given||'답변 없음')}</p></div><div><span>정답</span><p>${esc(a.answer)}</p></div></div>`).join('')}<div class="actions"><button data-record="${esc(r.id)}" data-wrong-only="true">오답 확인</button><button data-review="${r.expressionId}">다시 학습</button></div></article>`).join(''):'<p class="muted">아직 오답이 없어요.</p>'}</section>`:`<section class="card study-log-list">${h.length?h.map(historyRow).join(''):'<p class="muted">첫 학습을 시작해보세요.</p>'}</section>`}`}
function historyRow(r){return `<div class="history-item"><div class="row"><b>${esc(r.english)}</b><span class="tag reward">${r.score}점</span></div><small>${esc(r.date)} · ${esc(r.meaning)} · 정답 ${r.correct} / 오답 ${r.wrong}</small><p class="record-question-types">${[...new Set((r.answers||[]).map(a=>QUIZ_NAMES[a.type]).filter(Boolean))].map(t=>`<strong>${esc(t)}</strong>`).join(' · ')}</p><div class="actions"><button data-record="${esc(r.id)}">문제 확인</button></div></div>`}
function closeAnswerReview(){const destination=historyReview?.returnPage||'history';historyReview=null;if(destination==='records'){historyTab='all';page='history'}else page=destination;render();window.scrollTo(0,0)}
function openDaySummary(day){if(!db.session)return;const records=profile().history.filter(r=>r.major===profile().major&&r.scheduledDate===day);$('#day-summary-title').textContent=day+' 학습';$('#day-summary-content').innerHTML=records.length?`<p class="muted">학습 ${records.length}회 · ${records.reduce((sum,r)=>sum+r.score,0)}점</p>${records.map(r=>`<article class="day-summary-item"><h3>${esc(r.english)}</h3><p>${esc(r.meaning)}</p><small>${r.status==='late'?'늦게 완료':'완료'} · 정답 ${r.correct} / 오답 ${r.wrong}${r.date!==r.scheduledDate?' · 완료일 '+esc(r.date):''}</small><button class="primary wide" data-record="${esc(r.id)}">문제 확인</button></article>`).join('')}`:'<p class="muted">이 날짜의 완료한 학습 기록이 없습니다.</p>';$('#day-summary').showModal()}
function openAnswerReview(id,wrongOnly=false){if(!db.session)return;const record=profile().history.find(r=>r.id===id);if(!record){toast('학습 기록을 찾을 수 없습니다.');return}if(!record.answers?.length){toast('저장된 문제별 답안이 없습니다.');return}if($('#day-summary').open)$('#day-summary').close();const fromRecords=$('#expression-info').open||page==='records'||page==='history'&&historyTab==='all';if($('#expression-info').open)$('#expression-info').close();historyReview={returnPage:fromRecords?'records':['wrong-review','study-log'].includes(page)?page:'history',recordId:id,index:wrongOnly?Math.max(0,record.answers.findIndex(a=>!a.correct)):0};page='answer-review';render();window.scrollTo(0,0)}
function answerReviewView(){const r=profile().history.find(r=>r.id===historyReview?.recordId);if(!r)return '<p>학습 기록을 찾을 수 없습니다.</p>';const i=historyReview.index,a=r.answers[i],names={...QUIZ_NAMES,choice:'객관식'};let answer='';if(['choice','scenario'].includes(a.type)&&Array.isArray(a.options)&&a.options.length){answer=`<div class="choices saved-choices">${a.options.map((option,index)=>{const chosen=Number.isInteger(a.selectedIndex)?index===a.selectedIndex:option===a.given,right=option===a.answer;return `<div class="saved-option ${chosen?'was-selected':''} ${right?'was-correct':''} ${chosen&&!a.correct?'was-wrong':''}"><span>${index+1}. ${esc(option)}</span><small>${chosen?'내 선택':''}${chosen&&right?' · ':''}${right?'정답':''}</small></div>`}).join('')}</div>`}else if(a.type==='match'&&a.pairs){answer=`<div class="saved-matches">${a.pairs.map(p=>`<div class="saved-option ${p.correct?'was-correct':'was-wrong'}"><div><b>${esc(p.english)}</b><p>내 선택: ${esc(p.selectedMeaning)}</p><small>정답: ${esc(p.meaning)}</small></div><span>${p.correct?'✓':'✕'}</span></div>`).join('')}</div>`}else if(a.type==='order'){answer=`<h3>내가 배열한 순서</h3><div class="saved-words">${(a.selectedWords||String(a.given||'').split(' ')).map(word=>`<span>${esc(word)}</span>`).join('')}</div>`}else if(a.type==='speaking'){answer=`<div class="hint">${esc(a.given)}${a.requiredRepetitions?' / 목표 '+a.requiredRepetitions+'회':''}<p class="muted">말하기는 반복 완료 기록입니다. 음성은 녹음하지 않습니다.</p></div>`}else{answer=`<div class="saved-answer"><small>내가 선택한 답</small><p>${esc(a.given||'저장된 답 없음')}</p></div>${a.type==='choice'?'<p class="muted review-note">이 기록에는 당시 선택지 목록이 없어, 저장된 내 답과 정답을 표시합니다.</p>':''}`}return `<section class="quiz answer-review"><div class="row"><button id="close-answer-review">${historyReview.returnPage==='records'?'기록으로':historyReview.returnPage==='wrong-review'?'오답 복습으로':historyReview.returnPage==='study-log'?'학습 내역으로':'학습 기록으로'}</button><b>${i+1} / ${r.answers.length} 문제</b></div><p class="review-note muted">${esc(r.date)} · 저장된 답안 확인</p><div class="progress"><span style="width:${(i+1)/r.answers.length*100}%"></span></div><div class="quiz-expression"><small>${esc(MAJORS[r.major]||'')} · <strong class="quiz-type-name">${names[a.type]||'학습 문제'}</strong></small><h2>${esc(r.english)}</h2><p>${esc(r.meaning)}</p></div><p class="review-note">${a.prompt?esc(a.prompt):''}</p><h3>${a.type==='match'?'영어 표현과 뜻의 짝을 맞추세요':a.type==='scenario'?'상황에 맞는 영어 표현을 고르세요':a.type==='order'?'영어 단어를 올바른 순서로 배열하세요':a.type==='choice'?'표현에 알맞은 뜻을 선택하세요':'영어 표현을 소리 내어 반복하세요'}</h3>${answer}<button class="wide retry-saved" id="retry-saved-question">이 문제 다시 풀기</button><div class="feedback ${a.correct?'':'wrong'}"><b>${a.correct?'✓ 정답으로 제출한 문제':'✕ 오답으로 제출한 문제'}</b><p>내 답: ${esc(a.given)}</p><p>정답: ${esc(a.answer)}</p></div><div class="actions"><button id="previous-answer" ${i===0?'disabled':''}>이전 문제</button><button class="primary" id="next-answer">${i===r.answers.length-1?'확인 완료':'다음 문제'}</button></div></section>`}

function iconSvgBadge(){return icon('achievements')}
function recordGroups(){const groups=new Map();for(const r of profile().history){const key=r.expressionId||r.english;if(!groups.has(key))groups.set(key,[]);groups.get(key).push(r)}return [...groups.entries()].map(([id,rows])=>({id,rows:rows.sort((a,b)=>b.date.localeCompare(a.date)),latest:rows.reduce((a,b)=>a.date>b.date?a:b)})).sort((a,b)=>b.latest.date.localeCompare(a.latest.date))}
function recordsView(){const groups=db.session?sortedRecords(recordGroups(),'records'):[];return `<section class="records-page"><button class="wide records-achievements" id="open-achievements">${icon('achievements')}<span>업적</span><span aria-hidden="true">›</span></button><div class="records-heading"><h1>기록</h1>${db.session?`<small>${groups.length}개 표현</small>`:''}</div>${db.session?analysisLink('records'):''}<h2 class="record-list-heading">전체 전공 학습 내역</h2>${db.session?recordSortControl('records',groups.length):''}<div class="expression-records">${!db.session?'<p class="muted">표현별 학습 기록은 로그인 후 확인할 수 있습니다.</p><button class="wide" data-nav="login">로그인</button>':groups.length?groups.map(g=>{const r=g.latest,rate=r.total?Math.round(r.correct/r.total*100):0;return `<button class="expression-record" data-expression="${esc(g.id)}" aria-label="${esc(r.english)} 학습 정보"><span class="expression-record-text"><b>${esc(r.english)}</b><span>${esc(r.meaning)}</span><small>${esc(MAJORS[r.major]||'')} · ${esc(r.date)}${g.rows.length>1?' · '+g.rows.length+'회 학습':''}</small></span><span class="record-ring" style="--record-angle:${rate*3.6}deg" aria-label="정답률 ${rate}%"><span>${rate}<small>%</small></span></span><span class="record-chevron" aria-hidden="true">›</span></button>`}).join(''):'<div class="records-empty"><h2>아직 학습 기록이 없습니다.</h2><p class="muted">표현을 학습하면 이곳에 기록이 쌓입니다.</p><button class="primary" data-nav="daily">학습하러 가기</button></div>'}</div></section>`}
function personalBests(){const h=profile().history;let longest=0,run=0,last=null;for(const day of [...new Set(h.map(r=>r.date))].sort()){if(last){const d=new Date(last+'T12:00:00');d.setDate(d.getDate()+1);run=dateKey(d)===day?run+1:1}else run=1;longest=Math.max(longest,run);last=day}return [{name:'한 번에 얻은 최고 점수',value:h.reduce((v,r)=>Math.max(v,r.score),0),unit:'점'},{name:'모두 맞힌 학습',value:h.filter(r=>r.correct===r.total).length,unit:'회'},{name:'최장 연속 학습',value:longest,unit:'일'}]}
function openAchievements(){const content=achievements().replace('<h1>업적</h1>','');$('#achievements-content').innerHTML=`<section class="personal-bests"><h3>개인 최고 기록</h3><div class="personal-best-list">${personalBests().map(x=>`<article><small>${x.name}</small><b>${x.value}<span>${x.unit}</span></b></article>`).join('')}</div></section><h3 class="rewards-heading">업적</h3>${content}`;$('#achievements-dialog').showModal()}
function openExpressionInfo(id){if(!db.session)return;const group=recordGroups().find(g=>g.id===id);if(!group)return;$('#expression-info-content').innerHTML=`<div class="expression-info-title"><h3>${esc(group.latest.english)}</h3><p class="muted">${esc(group.latest.meaning)}</p></div><h3 class="expression-info-label">학습 내역</h3>${group.rows.map(r=>`<article class="expression-attempt"><span class="attempt-status ${r.wrong?'has-errors':''}" aria-hidden="true">${r.wrong?'!':'✓'}</span><div><b>${r.status==='late'?'늦게 완료한 학습':'학습 완료'}</b><small>${esc(r.date)} · ${r.score}점</small><small>정답 ${r.correct} / 오답 ${r.wrong}</small></div><button data-record="${esc(r.id)}">문제 확인</button></article>`).join('')}`;$('#expression-info').showModal()}
function achievements(){const s=stats(),p=profile(),count=Object.keys(p.achievements).length;return `<h1>업적</h1><p class="muted">${db.session?'달성 조건과 진행 상황을 확인하세요.':'일일 학습에서 달성한 기기 내 업적입니다.'}</p><section class="card" style="margin:24px 0"><div class="row"><b>달성한 업적</b><b>${count} / ${achievementDefs.length}</b></div><div class="progress"><span style="width:${count/achievementDefs.length*100}%"></span></div><small>${Math.round(count/achievementDefs.length*100)}% 달성</small></section><div class="badges">${achievementDefs.map(([id,name,condition,target,value,icon])=>{const earned=p.achievements[id],progress=earned?target:Math.min(target,value(s));return `<section class="card ${earned?'earned':''}"><div class="row"><div class="badge-icon" aria-hidden="true">${iconSvgBadge()}</div><span class="tag">${earned?'✓ 달성':'도전 중'}</span></div><h3>${name}</h3><p class="muted">${condition}</p><div class="progress"><span style="width:${progress/target*100}%"></span></div><small>${progress} / ${target}${earned?` · ${earned} 획득`:''}</small></section>`}).join('')}</div>`}
function bestStudyStreak(h){let best=0,run=0,last=null;for(const day of [...new Set(h.map(r=>r.date))].sort()){const d=last?new Date(last+'T12:00:00'):null;if(d)d.setDate(d.getDate()+1);run=d&&dateKey(d)===day?run+1:1;best=Math.max(best,run);last=day}return best}
let rankingTab='score';
function eligibleCountdownBests(p){const result={};for(const r of p.countdownRuns||[]){if(r.rankEligible!==true||!Number.isFinite(r.ms)||r.ms<=0)continue;const key=r.major+':'+r.signature;if(!result[key]||r.ms<result[key].ms)result[key]={...r}}return result}
function invalidateOfflineRanking(){if(isOnline())return;if(quiz)quiz.rankEligible=false;if(typeof fallGame!=='undefined'&&fallGame?.phase==='playing')fallGame.rankEligible=false}
function publishLocalRankings(){if(!localMode()||!isOnline())return false;db.rankingProfiles={};for(const a of db.localAccounts){const p=db.profiles[a.id]||{};db.rankingProfiles[a.id]={history:(p.history||[]).filter(r=>r.rankEligible===true).map(r=>({date:r.date,score:r.score})),countdownBests:eligibleCountdownBests(p)}}return true}
function extraRankings(){if(!isOnline())return '<p class="muted">온라인 연결 후 랭킹을 확인할 수 있습니다.</p>';if(!localMode())return `<section class="card ranking-list"><div class="ranking-list-title"><h2>${rankingTab==='streak'?'최장 연속 학습':'카운트다운 최단 완료'}</h2></div><p class="muted" id="server-metric-status" role="status">순위를 불러오는 중…</p><div id="server-metric-rows"></div></section>`;const major=profile().major,signature=expressions.filter(w=>w.major===major).map(w=>w.id).sort().join('|'),accounts=db.localAccounts;const people=accounts.map(a=>({id:a.id,nickname:a.example?(a.nickname||'예시 학습자'):(a.identity||a.nickname||'학습자'),p:db.rankingProfiles?.[a.id]||{}}));const sections=[{title:'최장 연속 학습',unit:'일',rows:people.map(a=>({...a,value:bestStudyStreak(a.p.history||[])})).sort((a,b)=>b.value-a.value)},{title:'단어 카운트다운 최단 완료',unit:'초',rows:people.map(a=>({...a,value:a.p.countdownBests?.[major+':'+signature]?.ms})).filter(a=>Number.isFinite(a.value)&&a.value>0).sort((a,b)=>a.value-b.value)}];return sections.map((section,j)=>{if((rankingTab==='streak'?0:1)!==j)return '';let rank=0,last;return `<section class="card ranking-list extra-ranking"><div class="extra-ranking-heading"><h2>${section.title}</h2><p class="muted">${j?esc(MAJORS[major]||'전공 선택 필요')+' · 전체 표현 양방향 완료 · 짧은 시간 순':'온라인 인정 학습일 기준 · 최장 연속 일수'}</p></div><div class="ranking-columns" aria-hidden="true"><span>순위</span><span>학습자</span><span>${j?'완료 시간':'연속 기록'}</span></div>${section.rows.map((a,i)=>{if(a.value!==last)rank=i+1;last=a.value;return `<div class="history-item ranking-entry ${a.id===db.session.user.id?'is-me':''}"><span class="rank-number">${rank}</span><div class="rank-person"><span>${esc(a.nickname)}</span>${a.id===db.session.user.id?'<small class="rank-mine-label">나</small>':''}</div><span class="rank-score">${j?(a.value/1000).toFixed(2):a.value}<small>${section.unit}</small></span></div>`}).join('')||'<p class="ranking-empty muted">아직 완료 기록이 없습니다.</p>'}</section>`}).join('')}
function ranking(){if(!isOnline())return `<section class="ranking-offline"><h2>온라인 연결이 필요합니다</h2><p class="muted">오프라인 학습·게임은 개인 기록으로만 저장되며, 연결 후에도 랭킹에 반영되지 않습니다.</p></section>`;publishLocalRankings();if(!db.session)return locked(localMode()?'기기 내 순위는 로컬 계정 로그인 후 이용할 수 있습니다.':'랭킹은 로그인 및 인터넷 연결이 필요합니다.');return `<section class="ranking-page"><div class="page-head"><div><h1>학습 랭킹</h1><p class="muted">${localMode()?'이 기기에 등록한 계정들의 기록입니다.':'누적 학습 점수로 순위를 확인하세요.'}</p></div>${rankingTab==='score'?'<button id="refresh-ranking">갱신</button>':''}</div><div class="ranking-tabs" role="group" aria-label="랭킹 종류">${[['score','누적 점수'],['streak','연속 학습'],['countdown','카운트다운']].map(([id,label])=>`<button data-ranking-tab="${id}" aria-pressed="${rankingTab===id}">${label}</button>`).join('')}</div>${rankingTab==='score'?`<div id="ranking-me" class="ranking-me card" hidden></div><section class="card ranking-list"><div class="row ranking-list-title"><h2>${localMode()?'기기 내 순위':'전체 순위'}</h2><small id="ranking-count"></small></div><p class="muted" id="ranking-status" role="status">${localMode()||isOnline()?'순위를 불러오는 중…':'오프라인 상태에서는 랭킹을 조회할 수 없습니다.'}</p><div class="ranking-columns" aria-hidden="true"><span>순위</span><span>학습자</span><span>누적 점수</span></div><div id="ranking-data"></div></section>`:extraRankings()}${localMode()?'<p class="ranking-note muted">이 기기의 로컬 계정 기준이며, 다른 기기의 사용자 순위는 포함하지 않습니다.</p>':''}</section>`}

function settings(){const p=profile();return `<section class="settings"><h1>설정</h1><section class="card settings-section" aria-labelledby="learning-heading"><h2 id="learning-heading">학습</h2><div class="setting-field"><label for="major-setting">전공</label><select id="major-setting">${Object.entries(MAJORS).map(([id,n])=>`<option value="${id}" ${p.major===id?'selected':''}>${n}</option>`).join('')}</select></div></section><section class="card settings-section" aria-labelledby="appearance-heading"><h2 id="appearance-heading">화면</h2><div class="setting-field"><label for="theme-setting">화면 테마</label><select id="theme-setting">${[['light','라이트 모드'],['dark','다크 모드'],['system','시스템 기본 테마']].map(([id,n])=>`<option value="${id}" ${db.theme===id?'selected':''}>${n}</option>`).join('')}</select></div><div class="color-setting"><h3 id="color-heading">주요 색상</h3><p class="setting-description">버튼, 선택한 메뉴, 학습 진행률에 적용됩니다.</p><div class="color-presets" role="group" aria-labelledby="color-heading">${COLOR_PRESETS.map(([name,color])=>`<button type="button" class="color-swatch" data-color="${color}" style="--swatch:${color}" aria-label="${name}" title="${name}" aria-pressed="${db.primaryColor===color}"><span aria-hidden="true"></span><small>${name}</small></button>`).join('')}</div><div class="custom-color"><div class="setting-field color-picker-field"><label for="primary-color">직접 선택</label><input id="primary-color" type="color" value="${db.primaryColor}"></div><div class="setting-field color-code-field"><label for="primary-hex">색상 코드</label><input id="primary-hex" type="text" value="${db.primaryColor}" maxlength="7" pattern="#[0-9a-fA-F]{6}" spellcheck="false" aria-describedby="color-error"></div><button id="reset-color" type="button">기본색으로</button></div><p id="color-error" class="error" role="status"></p></div></section><section class="card settings-section" aria-labelledby="account-heading"><h2 id="account-heading">계정</h2><div class="account-summary"><strong>${esc(db.session?.user?.nickname||'비로그인')}</strong><p class="setting-description">${esc(db.session?.user?.email||(db.session?'이 기기에 등록한 로컬 계정':'계정 없이 일일 학습을 이용하고 있습니다.'))}</p></div><button class="wide" id="logout">${db.session?'로그아웃':'로그인 화면으로'}</button></section><section class="card settings-section" aria-labelledby="data-heading"><h2 id="data-heading">학습 데이터</h2><p class="setting-description" id="sync-status">${db.session?(localMode()?'학습 기록은 이 기기에 저장됩니다.':p.pending?'서버에 동기화할 학습 기록이 있습니다.':'학습 기록을 서버와 동기화할 수 있습니다.'):'학습 기록은 이 기기에 저장됩니다.'}</p>${db.session?`<button class="wide" id="sync">${localMode()?'기기 내 계정 백업':'서버와 동기화'}</button>`:''}${localMode()?'<div class="actions backup-actions"><button id="backup-export">백업 내보내기</button><button id="backup-import">백업 불러오기</button></div>':''}<div class="reset-setting"><div><h3>학습 기록 초기화</h3><p class="setting-description">학습 기록, 점수, 업적, 뽑기 결과를 삭제합니다.<br>전공과 화면 설정은 유지됩니다.</p></div><button class="danger" id="reset">초기화</button></div></section><footer class="settings-about"><strong>Major Words</strong><span>버전 1.20.3 · Smalltalk Learning</span></footer></section>`}

let serverAccessToken=null;
const serverClient=window.MajorWordsServerClient.create(CONFIG,{getToken:()=>serverAccessToken,isOnline});
async function api(path,body,method){if(path.startsWith('rankings')&&!isOnline())throw Error('랭킹은 온라인에서만 이용할 수 있습니다.');if(localMode())return window.MajorWordsLocalService.request(path,body,method,{state:db,save,newId:uid});const options=path==='sync'?{idempotencyKey:db.session?.user.id+':'+(profile().resetAt||'initial')+':'+(profile().revision||0)}:{};return serverClient.request(path,body,method,options)}
async function authenticate(form){const data=Object.fromEntries(new FormData(form)),signup=page==='signup';if(signup&&(!/^(?=.*[A-Za-z])(?=.*\d).{8,}$/.test(data.password)||data.password!==data.confirm)){$('#form-error').textContent='영문과 숫자를 포함한 8자 이상 비밀번호와 동일한 확인값을 입력해주세요.';return}if(!data.identity.trim()){$('#form-error').textContent='이메일 또는 아이디를 입력해주세요.';return}const btn=form.querySelector('button');btn.disabled=true;try{const result=await api(signup?'auth/register':'auth/login',{identity:data.identity.trim(),password:data.password});if(!result.user?.id)throw Error('서버 응답에 계정 정보가 없습니다.');if(!localMode()&&CONFIG.apiAuthMode==='bearer'){if(!result.accessToken)throw Error('서버 응답에 인증 토큰이 없습니다.');serverAccessToken=result.accessToken}db.session={user:result.user,mode:localMode()?'local':'server'};guest=false;if(result.profile){db.profiles[result.user.id]=mergeProfiles(db.profiles[result.user.id],result.profile)}const p=profile();if(result.user.major&&!p.majorPending)p.major=result.user.major;save();page=signup||!p.major?'major':'daily';render();sync()}catch(e){if($('#form-error'))$('#form-error').textContent=e.message}finally{if(btn.isConnected)btn.disabled=false}}
function normalizeProfile(p){return{...fresh(),...p,completed:{ee:p.completed?.ee||[],com:p.completed?.com||[]},draws:p.draws||{},achievements:p.achievements||{},history:p.history||[]}}
function mergeSavedRows(remote=[],local=[]){return [...new Map([...remote,...local].map(r=>[r.id||JSON.stringify(r),r])).values()]}
function mergeProfiles(local,remote){const r=normalizeProfile(remote);if(!local)return r;const l=normalizeProfile(local);if(l.resetPending||(l.resetAt&&(!r.resetAt||l.resetAt>r.resetAt)))return l;if(r.resetAt&&(!l.resetAt||r.resetAt>l.resetAt))return r;return {...l,...r,quizDrafts:l.quizDrafts||r.quizDrafts,listSort:l.listSort||r.listSort,countdownRuns:mergeSavedRows(r.countdownRuns,l.countdownRuns),aiBattles:mergeSavedRows(r.aiBattles,l.aiBattles),countdownBests:{...r.countdownBests,...l.countdownBests},major:l.pending?l.major:r.major,history:[...new Map([...r.history,...l.history].map(x=>[x.id,x])).values()],completed:{ee:[...new Set([...r.completed.ee,...l.completed.ee])],com:[...new Set([...r.completed.com,...l.completed.com])]},draws:{...r.draws,...l.draws},achievements:{...r.achievements,...l.achievements},created:l.created<r.created?l.created:r.created,pending:l.pending,revision:l.revision,majorPending:l.majorPending,resetPending:l.resetPending,resetAt:l.resetAt,achievementState:{...r.achievementState,...l.achievementState}}}
async function sync(){if(publishLocalRankings())save();if(!db.session||!serviceAvailable()||syncing)return;syncing=true;const accountId=db.session.user.id,p=profile(),revision=p.revision||0;try{if(p.resetPending){const resetAt=p.resetAt;await api('learning',undefined,'DELETE');if(p.resetAt===resetAt)p.resetPending=false}if(db.session?.user.id!==accountId||db.profiles[accountId]!==p)return;if(p.majorPending){const major=p.major;await api('account/major',{major},'PUT');if(p.major===major)p.majorPending=false}if(db.session?.user.id!==accountId||db.profiles[accountId]!==p)return;const result=await api('sync',{profile:JSON.parse(JSON.stringify(p))});if(db.session?.user.id!==accountId||db.profiles[accountId]!==p)return;if(result.profile){const merged=mergeProfiles(p,result.profile);Object.assign(p,merged)}p.pending=(p.revision||0)!==revision||p.resetPending||p.majorPending;updateAchievementState();save();if($('#sync-status'))$('#sync-status').textContent=p.pending?'새 기록 저장 대기 중':localMode()?'기기 내 계정 백업 완료':'서버 동기화 완료';}catch(e){p.pending=true;save();if($('#sync-status'))$('#sync-status').textContent=`동기화 대기 · ${e.message}`}finally{syncing=false;if(db.session&&serviceAvailable()&&db.profiles[db.session.user.id]!==p&&profile().pending)setTimeout(sync,0)}}

async function selectMajor(id){if(!MAJORS[id]||busy)return;const p=profile();p.major=id;p.majorPending=!!db.session;markPending(p);save();page='daily';render();if(db.session){toast(localMode()?'전공을 변경했습니다. 기기 계정에 저장합니다.':isOnline()?'전공을 변경했습니다. 계정 동기화를 진행합니다.':'전공을 변경했습니다. 연결 복구 후 계정에 반영합니다.');sync()}}
let drawTestResult=null;
function drawView(){const draw=drawTestResult||currentDraw(),word=findWord(draw?.id);return `<section class="draw-page"><h1>${drawTestResult?'추첨 테스트':'표현 뽑기'}</h1><p class="muted">${esc(MAJORS[profile().major])}${drawTestResult?' · 학습 기록에 반영되지 않습니다':''}</p><div class="slot" id="slot"><div>${word?`<strong>${esc(word.english)}</strong><small class="draw-probability">${probabilityText(draw.probability)}</small><p>${esc(word.meaning)}</p><span class="tag">난이도 ${word.difficulty} / 5</span>`:'<p>표현을 뽑고 있습니다.</p>'}</div></div><button class="primary wide" id="confirm-draw">확인</button></section>`}
async function draw(test=false){
  test=test===true;if(busy||!test&&currentDraw()&&!currentDraw().done)return;
  const p=profile(),pool=expressions.filter(e=>e.major===p.major&&(test||!p.completed[p.major].includes(e.id)));if(!pool.length)return;
  const button=$('#draw');if(button)button.disabled=true;
  const key=drawKey(),weights=pool.map(drawWeight);let r=Math.random()*weights.reduce((a,b)=>a+b,0),selected=pool[pool.length-1];
  for(let i=0;i<pool.length;i++){r-=weights[i];if(r<0){selected=pool[i];break}}
  // 결과를 먼저 저장하므로 WebView가 추첨 도중 종료돼도 재추첨하지 않습니다.
  drawTestResult=test?{id:selected.id,done:false,probability:drawProbability(selected,pool)}:null;if(!test){p.draws[key]={id:selected.id,done:false,probability:drawProbability(selected,pool)};markPending(p);save()}page='draw';render();window.scrollTo(0,0);busy=true;$('#confirm-draw').disabled=true;$('#confirm-draw').textContent='추첨 중…';
  const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
  const slot=$('#slot'),steps=reduced?10:54,rowHeight=Math.max(76,Math.min(116,Math.round(window.innerHeight/7))),winnerIndex=2;
  const rows=Array.from({length:steps+winnerIndex+3},(_,i)=>i===winnerIndex?selected:pool[i%pool.length]);
  slot.className='slot drawing';slot.style.setProperty('--draw-row-height',rowHeight+'px');slot.setAttribute('aria-busy','true');slot.innerHTML=`<div class="reel-marker" aria-hidden="true"></div><div class="reel-track" aria-hidden="true">${rows.map(w=>`<div class="reel-row"><span>${esc(w.english)}</span><small>${probabilityText(drawProbability(w,pool))}</small></div>`).join('')}</div><span class="sr-only" role="status">전공 영어 표현을 추첨 중입니다.</span>`;
  const track=slot.querySelector('.reel-track'),start=-(steps+winnerIndex)*rowHeight,end=-winnerIndex*rowHeight;
  track.style.transform=`translate3d(0,${start}px,0)`;
  const duration=reduced?900:1800;
  try{await new Promise(resolve=>{let started=null;function frame(now){if(!track.isConnected){resolve();return}if(started===null)started=now;const t=Math.min(1,(now-started)/duration),eased=t<.4?(t/.4)*.65:.65+.35*(1-Math.pow(1-(t-.4)/.6,3));track.style.transform=`translate3d(0,${start+(end-start)*eased}px,0)`;if(t<1)requestAnimationFrame(frame);else resolve()}requestAnimationFrame(frame)});await new Promise(resolve=>setTimeout(resolve,30));}
  finally{busy=false;render();toast(`${selected.english} ${test?'테스트 완료':'추첨 완료'}`);if(!test)sync()}
}

async function fetchMetricRanking(){const target=$('#server-metric-rows'),status=$('#server-metric-status'),metric=rankingTab;if(!target||!isOnline())return;try{const query=new URLSearchParams({metric:metric==='streak'?'streak':'countdown'});if(metric==='countdown'){query.set('major',profile().major||'');query.set('contentSignature',expressions.filter(w=>w.major===profile().major).map(w=>w.id).sort().join('|'))}const result=await api('rankings?'+query);if(!Array.isArray(result.users))throw Error('랭킹 응답 형식이 올바르지 않습니다.');if(!target.isConnected||!isOnline()||rankingTab!==metric)return;status.textContent=metric==='streak'?'온라인 인정 학습일 기준':MAJORS[profile().major]+' · 온라인 인정 완료 시간';target.innerHTML=result.users.map(u=>`<div class="history-item ranking-entry ${u.id===db.session?.user.id?'is-me':''}"><span class="rank-number">${esc(u.rank)}</span><div class="rank-person">${esc(u.nickname)}</div><span class="rank-score">${metric==='streak'?Number(u.streak)||0:((Number(u.ms)||0)/1000).toFixed(2)}<small>${metric==='streak'?'일':'초'}</small></span></div>`).join('')||'<p class="ranking-empty muted">아직 인정된 기록이 없습니다.</p>'}catch(e){if(status.isConnected)status.textContent=e.message}}
async function fetchRanking(){if(!isOnline())return;publishLocalRankings();const b=$('#refresh-ranking'),status=$('#ranking-status'),container=$('#ranking-data');if(!b||b.disabled)return;b.disabled=true;status.textContent='최신 랭킹을 불러오는 중…';try{const result=await api('rankings');if(!Array.isArray(result.users))throw Error('랭킹 데이터 형식이 올바르지 않습니다.');const rows=[...result.users].sort((a,b)=>b.score-a.score);if(!container.isConnected||!isOnline())return;status.textContent=`내 전체 순위: ${result.me?.rank??'집계 전'} · 누적 ${result.me?.score??'집계 전'}점`;status.classList.add('sr-only');const me=$('#ranking-me');me.hidden=false;me.innerHTML=`<div class="ranking-identity"><span class="ranking-avatar">${icon('ranking')}</span><div><small>내 학습 순위</small><h2>${esc(db.session.user.nickname||'나')}</h2></div></div><div class="ranking-metrics"><div><small>현재 순위</small><strong>${result.me?.rank?esc(result.me.rank)+'<small>위</small>':'집계 전'}</strong></div><div><small>누적 점수</small><strong>${result.me?.score!==undefined?Number(result.me.score).toLocaleString()+'<small>점</small>':'집계 전'}</strong></div></div>`;$('#ranking-count').textContent=rows.length+'명';container.innerHTML=rows.map((u,i)=>{const mine=u.id===db.session.user.id,rank=Number(u.rank)||i+1;return `<div class="history-item ranking-entry ${mine?'is-me':''}"><span class="rank-number ${rank<=3?'rank-leading':''}">${rank}</span><div class="rank-person"><span>${esc(u.nickname)}</span>${mine?'<small class="rank-mine-label">나</small>':''}</div><span class="rank-score">${(Number(u.score)||0).toLocaleString()}<small>점</small></span></div>`}).join('')||'<p class="ranking-empty muted">아직 등록된 학습자가 없습니다.</p>'}catch(e){if(status.isConnected){status.classList.remove('sr-only');status.textContent='랭킹 조회 제한 · '+e.message}}finally{if(b.isConnected)b.disabled=false}}

