function openBackup(importing){
  $('#backup-title').textContent=importing?'백업 불러오기':'백업 내보내기';
  $('#backup-description').textContent=importing?'기존 로컬 계정·학습 데이터를 교체합니다. 보관한 백업 데이터를 붙여넣은 뒤 불러오기를 누르세요.':'아래 데이터를 복사해 안전하게 보관하세요. 로컬 계정과 학습 기록이 포함됩니다.';
  const area=$('#backup-data');area.readOnly=!importing;area.value=importing?'':JSON.stringify({format:'major-words-backup',version:1,state:{...db,session:null}},null,2);
  $('#backup-apply').hidden=!importing;$('#backup-error').textContent='';$('#backup').showModal();if(!importing){area.focus();area.select()}
}
$('#backup-close').onclick=()=>$('#backup').close();
$('#backup-apply').onclick=()=>{
  try{
    const text=$('#backup-data').value;if(text.length>8_000_000)throw Error('백업 크기가 너무 큽니다.');
    const backup=JSON.parse(text),state=backup.state;
    if(backup.format!=='major-words-backup'||backup.version!==1||!state||!Array.isArray(state.localAccounts)||!state.profiles)throw Error('Major Words 백업 형식이 아닙니다.');
    const ids=new Set();for(const a of state.localAccounts){if(typeof a.id!=='string'||!a.id.startsWith('local-')||ids.has(a.id)||typeof a.identity!=='string'||typeof a.salt!=='string'||! /^[a-f0-9]{64}$/.test(a.hash)||!Number.isInteger(a.iterations)||a.iterations<1000||a.iterations>200000)throw Error('계정 백업 데이터가 올바르지 않습니다.');ids.add(a.id)}
    for(const p of Object.values(state.profiles)){if(!p||!Array.isArray(p.history)||!p.completed||!Array.isArray(p.completed.ee)||!Array.isArray(p.completed.com)||!p.draws||!p.achievements||(p.major!==null&&!MAJORS[p.major]))throw Error('학습 백업 데이터가 올바르지 않습니다.')}
    state.session=null;window.MajorWords.restoreState(state);$('#backup').close();toast('백업을 불러왔습니다. 복원한 로컬 계정으로 로그인해주세요.');
  }catch(e){$('#backup-error').textContent=e instanceof SyntaxError?'올바른 JSON 백업 데이터를 붙여넣어주세요.':e.message}
};
function speak(text){if(CONFIG.nativeSpeech&&nativePost({type:'speak',text,language:'en-US'}))return;if(!('speechSynthesis'in window)){toast('이 WebView의 발음 듣기는 Flutter 음성 연결이 필요합니다.');return}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(text);u.lang='en-US';u.rate=.85;speechSynthesis.speak(u)}
window.MajorWords={
  setAccessToken(token){if(localMode())return false;serverAccessToken=typeof token==='string'?token:null;return true},
  setOnline(value){nativeOnline=!!value;invalidateOfflineRanking();if(!['quiz','result','answer-review'].includes(page))render();if(nativeOnline)sync()},
  handleBack(){const picker=document.querySelector('#game-picker');if(picker?.open){picker.close();return true}if(page==='duel'&&duel?.showAnalysis){duel.showAnalysis=false;render();return true}if(page==='duel'){closeFriendConnection();cancelAnimationFrame(duelFrame);page='battle-hub';render();return true}if(['wrong-review','study-log'].includes(page)){page='history';render();return true}for(const id of ['achievements-dialog','expression-info'])if($('#'+id).open){$('#'+id).close();return true}if(quiz?.returnReview&&['quiz','result'].includes(page)){returnToSavedReview();return true}if($('#day-summary').open){$('#day-summary').close();return true}if(page==='answer-review'){closeAnswerReview();return true}if($('#backup').open){$('#backup').close();return true}if($('#confirm').open){$('#confirm').close('cancel');return true}if(busy)return true;if(['quiz','result','answer-review'].includes(page)){quiz=null;page='daily';render();return true}if(page==='signup'){page='login';render();return true}if(page==='analysis'){historyTab=analysisScope==='records'?'all':'major';page='history';render();return true}if(!['daily','login','major'].includes(page)){page='daily';render();return true}return false},
  restoreState(state){if(busy)return false;if(!state||typeof state!=='object'||!state.profiles)return false;db=state;db.theme=db.theme||'system';db.primaryColor=/^#[0-9a-f]{6}$/i.test(db.primaryColor||'')?db.primaryColor:'#58cc02';db.session=db.session||null;db.localAccounts=db.localAccounts||[];db.localBackups=db.localBackups||{};for(const id of Object.keys(db.profiles))db.profiles[id]=normalizeProfile(db.profiles[id]);quiz=null;page=db.session?(profile().major?'daily':'major'):'login';save();render();return true},
  exportState(){return JSON.parse(JSON.stringify(db))}
};
async function ensureExampleAccount(){
  if(!localMode()||CONFIG.exampleAccount===false)return;
  const identity='demo@example.com';
  if(db.localAccounts.some(a=>a.identity.toLowerCase()===identity))return;
  const result=await window.MajorWordsLocalService.request('auth/register',{identity,password:'Demo1234!'},'POST',{state:db,save,newId:uid});
  const account=db.localAccounts.find(a=>a.id===result.user.id);account.example=true;
  const p=fresh(),words=['ee','com'].flatMap(major=>expressions.filter(w=>w.major===major).slice(0,4));
  const relativeDate=offset=>{const d=new Date();d.setDate(d.getDate()+offset);return dateKey(d)};
  p.major='ee';p.created=relativeDate(-6);p.example=true;
  words.forEach((w,i)=>{
    const date=relativeDate(Math.min(i,6)-6),wrong=[1,4,6].includes(i)?1:0;
    const answers=[{type:'order',given:wrong?w.english.split(' ').reverse().join(' '):w.english,answer:w.english,correct:!wrong},{type:'choice',given:w.meaning,answer:w.meaning,correct:true},{type:'speaking',given:requiredRepeats+'회 반복',answer:w.english,correct:true}];
    p.history.push({id:uid(),date,scheduledDate:date,expressionId:w.id,english:w.english,meaning:w.meaning,major:w.major,difficulty:w.difficulty,correct:3-wrong,wrong,total:3,score:(3-wrong)*pointsPerCorrect,status:'done',answers});
    p.completed[w.major].push(w.id);p.draws[date+':'+w.major]={id:w.id,done:true,score:(3-wrong)*pointsPerCorrect};
  });
  for(const id of ['first','seven','streak3','streak7','perfect'])p.achievements[id]=today();
  p.achievementState=Object.fromEntries(achievementDefs.map(([id,,condition,target,value])=>[id,{condition,target,progress:p.achievements[id]?target:id==='hard'?0:words.length,achieved:!!p.achievements[id],achievedAt:p.achievements[id]||null}]));
  db.profiles[account.id]=p;db.localBackups[account.id]={profile:JSON.parse(JSON.stringify(p)),savedAt:new Date().toISOString()};save();
}
async function ensureAdditionalExamples(){
 if(!localMode()||CONFIG.exampleAccount===false)return;
 const specs=[['demo2@example.com','예시 · 꾸준한 학습자','ee',12,2,142000],['demo3@example.com','예시 · 통신 학습자','com',8,3,168000],['demo4@example.com','예시 · 빠른 도전자','ee',6,4,118000],['demo5@example.com','예시 · 첫 학습자','com',2,2,null]];
 for(const [identity,nickname,major,count,errorEvery,gameMs]of specs){
  if(db.localAccounts.some(a=>a.identity.toLowerCase()===identity))continue;
  const result=await window.MajorWordsLocalService.request('auth/register',{identity,password:'Demo1234!'},'POST',{state:db,save,newId:uid}),account=db.localAccounts.find(a=>a.id===result.user.id);account.example=true;account.nickname=nickname;
  const p=fresh(),pool=expressions.filter(w=>w.major===major);p.major=major;p.example=true;
  pool.slice(0,count).forEach((w,i)=>{const d=new Date();d.setDate(d.getDate()-(count-1-i));const date=dateKey(d),wrong=i%errorEvery===0,other=pool.find(x=>x.id!==w.id&&x.meaning!==w.meaning),options=[w.meaning,...pool.filter(x=>x.id!==w.id&&x.meaning!==w.meaning).slice(0,3).map(x=>x.meaning)],answers=[{type:'choice',given:wrong?other.meaning:w.meaning,answer:w.meaning,correct:!wrong,options,selectedIndex:wrong?1:0},{type:'order',given:w.english,answer:w.english,correct:true,selectedWords:w.english.split(' '),wordBank:w.english.split(' ')}];p.history.push({id:uid(),date,scheduledDate:date,expressionId:w.id,english:w.english,meaning:w.meaning,major,difficulty:w.difficulty,correct:wrong?1:2,wrong:wrong?1:0,total:2,score:(wrong?1:2)*pointsPerCorrect,status:'done',answers});p.completed[major].push(w.id);p.draws[date+':'+major]={id:w.id,done:true,score:(wrong?1:2)*pointsPerCorrect}});
  p.created=p.history[0].date;p.achievements.first=today();if(count>=7)p.achievements.seven=today();if(count>=3)p.achievements.streak3=today();if(count>=7)p.achievements.streak7=today();
  if(gameMs){const signature=pool.map(w=>w.id).sort().join('|'),record={major,signature,ms:gameMs,date:today(),questions:pool.length*2,example:true};p.countdownBests={[major+':'+signature]:record};p.countdownRuns=[{...record}]}
  db.profiles[account.id]=p;db.localBackups[account.id]={profile:JSON.parse(JSON.stringify(p)),savedAt:new Date().toISOString()};save();
 }
}
async function init(){try{expressions=window.MAJOR_WORDS_EXPRESSIONS;if(!Array.isArray(expressions)||!expressions.length)throw Error('학습 콘텐츠 번들이 없습니다.');await ensureExampleAccount();await ensureAdditionalExamples();for(const id of Object.keys(db.profiles))db.profiles[id]=normalizeProfile(db.profiles[id]);if(db.session&&((localMode()&&(db.session.mode==='server'||!db.localAccounts.some(a=>a.id===db.session.user.id)))||(!localMode()&&db.session.mode==='local'))){db.session=null;page='login';save()}if(db.session&&!profile().major)page='major';updateAchievementState();restoreScreen();render();if(!storageOK)toast('WebView 기기 저장소를 사용할 수 없습니다. Flutter 저장 연동이 필요합니다.');if('serviceWorker'in navigator&&['http:','https:'].includes(location.protocol))navigator.serviceWorker.register('sw.js').catch(()=>{});nativePost({type:'ready'});sync()}catch(e){$('#app').innerHTML=`<main><section class="card"><h1>학습 데이터를 불러오지 못했습니다</h1><p>expressions-data.js를 포함한 전체 파일을 Flutter assets에 넣어주세요.</p><p>${esc(e.message)}</p></section></main>`}}init();
